fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    debug_assert_eq!(arr1.len(), arr2.len(), "Input vectors must have the same length");

    let mut result = Vec::with_capacity(arr1.len());
    for (&a, &b) in arr1.iter().zip(arr2.iter()) {
        result.push(a ^ b);
    }
    result
}

// Optional: a version that accepts slices (more idiomatic/reusable).
