fn bit_wise_xor_slice(arr1: &[i32], arr2: &[i32]) -> Vec<i32> {
    debug_assert_eq!(arr1.len(), arr2.len(), "Input slices must have the same length");

    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a ^ b)
        .collect()
}